import{_ as a,o as r,c as i,a3 as t}from"./chunks/framework.B5WAEDB7.js";const f=JSON.parse('{"title":"Glossary","description":"Every term from ApptiveGrid explained concisely.","frontmatter":{"title":"Glossary","description":"Every term from ApptiveGrid explained concisely."},"headers":[],"relativePath":"en/referenz/glossar.md","filePath":"en/referenz/glossar.md","lastUpdated":1787319236000}'),n={name:"en/referenz/glossar.md"};function o(l,e,s,h,p,d){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#view">View</a></li><li><a href="#apptivescript">ApptiveScript</a></li><li><a href="#trigger">Trigger</a></li><li><a href="#block">Block</a></li><li><a href="#run">Run</a></li><li><a href="#entry">Entry</a></li><li><a href="#field">Field</a></li><li><a href="#filter">Filter</a></li><li><a href="#flow">Flow</a></li><li><a href="#form">Form</a></li><li><a href="#grid">Grid</a></li><li><a href="#grouping">Grouping</a></li><li><a href="#link">Link</a></li><li><a href="#portal">Portal</a></li><li><a href="#role">Role</a></li><li><a href="#step">Step</a></li><li><a href="#page">Page</a></li><li><a href="#seat">Seat</a></li><li><a href="#space">Space</a></li><li><a href="#column-type">Column type</a></li><li><a href="#trial-period">Trial period</a></li><li><a href="#link-relationship">Link (relationship)</a></li><li><a href="#webhook">Webhook</a></li><li><a href="#terms-you-can-ignore">Terms you can ignore</a></li></ul></nav><hr><h2 id="view" tabindex="-1">View <a class="header-anchor" href="#view" aria-label="Permalink to &quot;View&quot;">​</a></h2><p>A specific presentation of a <a href="#grid">Grid</a>: which entries are visible (filter), in what order (sorting), how they&#39;re bundled (grouping), and which columns appear.</p><p>A view does not change the data. There are seven types: Grid View, Kanban, Calendar, Map, Gallery, List, Timeline.</p><p>→ <a href="/en/ansichten/was-ist-eine-ansicht">What is a View</a></p><h2 id="apptivescript" tabindex="-1">ApptiveScript <a class="header-anchor" href="#apptivescript" aria-label="Permalink to &quot;ApptiveScript&quot;">​</a></h2><p>The expression language of ApptiveGrid. Used in formula columns, conditional block visibility, Flow conditions, and filters — every filter built through the interface <em>is</em> an ApptiveScript expression. → <a href="/en/apptivescript/was-ist-apptivescript">What is ApptiveScript</a></p><h2 id="trigger" tabindex="-1">Trigger <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;Trigger&quot;">​</a></h2><p>The event that starts a <a href="#flow">Flow</a>. Every Flow has exactly one. → <a href="/en/flows/trigger">Trigger</a></p><h2 id="block" tabindex="-1">Block <a class="header-anchor" href="#block" aria-label="Permalink to &quot;Block&quot;">​</a></h2><p>A building block of a <a href="#page">Page</a>: text, heading, image, input field, embedded view, analytics, or layout container. Blocks can contain other blocks.</p><p>→ <a href="/en/referenz/blocktypen">Block Types</a></p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>A single execution of a <a href="#flow">Flow</a>. Called <em>Previous runs</em> in the interface. Every run has a status: <em>Done</em>, <em>Error</em>, or <em>Waiting</em>.</p><p>→ <a href="/en/flows/durchlaufhistorie">Run history</a></p><h2 id="entry" tabindex="-1">Entry <a class="header-anchor" href="#entry" aria-label="Permalink to &quot;Entry&quot;">​</a></h2><p>A row in a <a href="#grid">Grid</a>. In some places in the interface also called <em>Entity</em> or <em>Record</em> — they mean the same thing.</p><h2 id="field" tabindex="-1">Field <a class="header-anchor" href="#field" aria-label="Permalink to &quot;Field&quot;">​</a></h2><p>A column of a <a href="#grid">Grid</a>. Every field has a <a href="#column-type">column type</a>. The terms <em>Field</em> and <em>Column</em> mean the same thing.</p><p>→ <a href="/en/referenz/spaltentypen">Column Types</a></p><h2 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h2><p>A rule in a <a href="#view">View</a> that determines which entries are visible. Filters can be grouped with <strong>and</strong>/<strong>or</strong>, up to three levels deep.</p><p>A <strong>temporary filter</strong> applies only to you and only in this session; a saved filter applies to everyone who sees the view.</p><p>→ <a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></p><h2 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h2><p>An automated process made up of <a href="#step">steps</a>. Begins with exactly one <a href="#trigger">trigger</a>, followed by actions and helpers.</p><p>→ <a href="/en/flows/was-ist-ein-flow">What is a Flow</a></p><h2 id="form" tabindex="-1">Form <a class="header-anchor" href="#form" aria-label="Permalink to &quot;Form&quot;">​</a></h2><p>An input mask for a <a href="#grid">Grid</a>. Can create new entries or edit existing ones. People filling it out don&#39;t need an ApptiveGrid account, unless access is restricted.</p><p>→ <a href="/en/formulare/formular-erstellen">Creating a form</a></p><h2 id="grid" tabindex="-1">Grid <a class="header-anchor" href="#grid" aria-label="Permalink to &quot;Grid&quot;">​</a></h2><p>A table of structured data — the data store. Every column has a fixed type.</p><p>Not to be confused with a <a href="#view">View</a>, which only determines the presentation.</p><p>→ <a href="/en/grids/grid-anlegen">Your first Grid</a></p><h2 id="grouping" tabindex="-1">Grouping <a class="header-anchor" href="#grouping" aria-label="Permalink to &quot;Grouping&quot;">​</a></h2><p>Bundles entries in a <a href="#view">View</a> by the values of a field. Each group can display an aggregate: Sum, Average, Minimum, Maximum, Filled, Empty, Checked, Unchecked.</p><h2 id="link" tabindex="-1">Link <a class="header-anchor" href="#link" aria-label="Permalink to &quot;Link&quot;">​</a></h2><p>An externally shareable address. ApptiveGrid generates links for forms, views, <a href="#portal">portals</a>, Flow starts, and invitations.</p><p>All links of a <a href="#space">Space</a> are listed together in one place.</p><p>→ <a href="/en/zusammenarbeit/externe-links">External links overview</a></p><h2 id="portal" tabindex="-1">Portal <a class="header-anchor" href="#portal" aria-label="Permalink to &quot;Portal&quot;">​</a></h2><p>A published <a href="#page">page</a> — reachable via a portal link, shareable, and embeddable in websites.</p><p>→ <a href="/en/seiten/portal-veroeffentlichen">Publishing a portal</a></p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p>Determines what a person is allowed to do in a <a href="#space">Space</a>. Four levels: <strong>Owner</strong>, <strong>Manage</strong>, <strong>Edit</strong>, <strong>View</strong>.</p><p>Only <em>View</em> is free; the others use up a <a href="#seat">seat</a>.</p><p>→ <a href="/en/zusammenarbeit/rollen">Roles</a></p><h2 id="step" tabindex="-1">Step <a class="header-anchor" href="#step" aria-label="Permalink to &quot;Step&quot;">​</a></h2><p>A single element of a <a href="#flow">Flow</a>. Three kinds: <strong>Triggers</strong>, <strong>Actions</strong>, <strong>Helpers</strong>.</p><p>→ <a href="/en/flows/aktionen">Actions</a></p><h2 id="page" tabindex="-1">Page <a class="header-anchor" href="#page" aria-label="Permalink to &quot;Page&quot;">​</a></h2><p>An interface composed of <a href="#block">blocks</a>. It&#39;s published as a <a href="#portal">portal</a>.</p><div class="warning custom-block"><p class="custom-block-title">Used for three different things</p><p>&quot;Page&quot; is used in the interface for three different things:</p><ol><li><strong>Page (portal)</strong> — this entry</li><li><strong>Form page</strong> — a section of a multi-page form</li><li><strong>Flow page</strong> — a page displayed by a Flow step</li></ol></div><p>→ <a href="/en/seiten/was-sind-seiten">What are pages</a></p><h2 id="seat" tabindex="-1">Seat <a class="header-anchor" href="#seat" aria-label="Permalink to &quot;Seat&quot;">​</a></h2><p>A license for a person with editing rights in a <a href="#space">Space</a>. Read access is free and doesn&#39;t use up a seat.</p><p>→ <a href="/en/zusammenarbeit/sitzplaetze">Seats</a></p><h2 id="space" tabindex="-1">Space <a class="header-anchor" href="#space" aria-label="Permalink to &quot;Space&quot;">​</a></h2><p>The top-level organizational unit. Contains Grids, pages, and Flows. Access rights, plan, and seats are all tied to the Space.</p><h2 id="column-type" tabindex="-1">Column type <a class="header-anchor" href="#column-type" aria-label="Permalink to &quot;Column type&quot;">​</a></h2><p>Determines what values a <a href="#field">field</a> can hold, how they&#39;re displayed and filtered, and whether they can be collected in forms.</p><p>Three types calculate their own value: <em>Use linked value</em>, <em>Calculate sum</em>, <em>Formula</em>.</p><p>→ <a href="/en/referenz/spaltentypen">Column Types</a></p><h2 id="trial-period" tabindex="-1">Trial period <a class="header-anchor" href="#trial-period" aria-label="Permalink to &quot;Trial period&quot;">​</a></h2><p>The period after creating a <a href="#space">Space</a> during which extended features are available. The remaining days are shown in the Space settings.</p><h2 id="link-relationship" tabindex="-1">Link (relationship) <a class="header-anchor" href="#link-relationship" aria-label="Permalink to &quot;Link (relationship)&quot;">​</a></h2><p>A connection between entries in two <a href="#grid">Grids</a>. Two types: <em>Link record</em> (one target) and <em>Link multiple records</em> (multiple targets).</p><p>Chains of links across several Grids are not possible.</p><p>→ <a href="/en/grids/verknuepfungen">Linking Grids</a></p><h2 id="webhook" tabindex="-1">Webhook <a class="header-anchor" href="#webhook" aria-label="Permalink to &quot;Webhook&quot;">​</a></h2><p>Two meanings, depending on direction:</p><ul><li><strong>Outgoing</strong> — a notification that ApptiveGrid sends to an external system on an event. Configured in the Space settings.</li><li><strong>Incoming</strong> — a Flow trigger through which an external system starts a Flow.</li></ul><p>→ <a href="/en/integrationen/webhooks">Webhooks</a> · <a href="/en/flows/webhook-trigger">Starting a Flow via webhook</a></p><hr><h2 id="terms-you-can-ignore" tabindex="-1">Terms you can ignore <a class="header-anchor" href="#terms-you-can-ignore" aria-label="Permalink to &quot;Terms you can ignore&quot;">​</a></h2><p>These appear in out-of-the-way corners of the interface and aren&#39;t needed for everyday work:</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><em>VirtualGrid</em></td><td>Internal name for <a href="#view">View</a></td></tr><tr><td><em>Entity</em></td><td>Internal name for <a href="#entry">Entry</a></td></tr><tr><td><em>Persistent Grid</em></td><td>Internal name for <a href="#grid">Grid</a></td></tr><tr><td><em>Stable</em> / <em>Enterprise</em></td><td>Operating variants of ApptiveGrid</td></tr></tbody></table>',79)])])}const g=a(n,[["render",o]]);export{f as __pageData,g as default};
